mapper.update:
/* com.biz.framework.mapper.pages.ApplypaymentapprmngMapper.confirmApplypayment */
UPDATE SETTLEMENTMST
    SET PAY_YM      = REPLACE(#{payYm}, '-', '')
WHERE CO_CODE       = #{loginCoId}
AND CONFIRM_SEQ     = #{confirmSeq}

mapper.select:
/* com.biz.framework.mapper.pages.ApplypaymentMapper.checkPayroll */
SELECT COUNT(*)
FROM PAYMENTETC
WHERE CO_CODE  = #{loginCoId}
  AND USER_ID  = #{userId}
  AND PAY_YM   = REPLACE(#{payYm}, '-', '')

mapper.insert:
/* com.biz.framework.mapper.pages.ApplypaymentapprmngMapper.cancelApplypayment */
UPDATE SETTLEMENTMST
SET PAY_YM          = null,
    FINAL_RATE      = null,
    FINAL_AMT       = null
WHERE CO_CODE       = #{loginCoId}
  AND CONFIRM_SEQ   = #{confirmSeq}
